changeSet.sql:
DO $$ DECLARE restriction record; BEGIN
 FOR restriction IN SELECT conname FROM pg_constraint WHERE conrelid='${ARENA_DB_SCHEMA}.academy_sport'::regclass AND contype='c' AND regexp_replace(pg_get_constraintdef(oid),'[[:space:]()]','','g') ILIKE 'CHECKtrainingORsessions'
 LOOP EXECUTE format('ALTER TABLE %I.academy_sport DROP CONSTRAINT %I','${ARENA_DB_SCHEMA}',restriction.conname); END LOOP;
END $$;
